"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { 
  Search, 
  Plus,
  LifeBuoy,
  MoreVertical,
  Mail,
  Phone,
  Calendar,
  Trash2,
  ShieldAlert
} from "lucide-react";
import { format } from "date-fns";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { useTechSupportUsers } from "@/features/users";
import { useDeleteUser } from "@/features/users"; // Using generic delete
import { toast } from "sonner";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";


export default function TechSupportPage() {
  const router = useRouter();
  const [searchTerm, setSearchTerm] = useState("");
  const [userToDelete, setUserToDelete] = useState<string | null>(null);

  const { data: usersResponse, isLoading } = useTechSupportUsers({ 
    search: searchTerm 
  });

  const deleteUserMutation = useDeleteUser();

  const users = usersResponse?.data || [];

  const handleDelete = () => {
      if(userToDelete) {
          deleteUserMutation.mutate(userToDelete, {
              onSuccess: () => {
                  toast.success("User deactivated successfully");
                  setUserToDelete(null);
              },
              onError: () => {
                  toast.error("Failed to deactivate user");
              }
          });
      }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 p-6 md:p-8 pt-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <LifeBuoy className="h-8 w-8 text-primary" />
            Tech Support
          </h1>
          <p className="mt-1 text-muted-foreground">Manage technical support staff and access.</p>
        </div>
        <div className="flex gap-2">
           <Button 
            className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-lg hover:shadow-xl transition-all"
            onClick={() => router.push('/admin/users/tech-support/new')}
           >
            <Plus className="mr-2 h-4 w-4" />
            Add Staff
          </Button>
        </div>
      </div>

      <Card className="border-border/60 shadow-sm bg-card/50 backdrop-blur-sm">
        <CardHeader className="pb-4">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-lg font-semibold">Staff Directory</CardTitle>
              <CardDescription>Browse and manage support team members</CardDescription>
            </div>
            <div className="relative w-full md:w-72">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search by name or email..."
                  className="pl-9 bg-background border-border/60 focus:border-primary/50 transition-colors"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
          </div>
        </CardHeader>
        <CardContent>
            {isLoading ? (
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {[1, 2, 3].map((i) => (
                        <div key={i} className="h-32 rounded-xl bg-muted/40 animate-pulse" />
                    ))}
                </div>
            ) : users.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground">
                    <ShieldAlert className="h-12 w-12 mx-auto mb-3 opacity-20" />
                    <p>No tech support staff found.</p>
                </div>
            ) : (
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {users.map((user: any) => (
                        <Card key={user.id} className="group hover:shadow-md transition-shadow duration-200 border-border/60 overflow-hidden">
                            <CardContent className="p-6">
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3">
                                        <Avatar className="h-12 w-12 border-2 border-background shadow-sm">
                                            <AvatarImage src={user.profile_picture || user.avatar} />
                                            <AvatarFallback className="bg-primary/10 text-primary font-medium text-lg">
                                                {user.first_name?.[0]}{user.last_name?.[0]}
                                            </AvatarFallback>
                                        </Avatar>
                                        <div>
                                            <h3 className="font-semibold text-foreground group-hover:text-primary transition-colors">
                                                {user.first_name} {user.last_name}
                                            </h3>
                                            <Badge variant={user.status === 'active' ? 'default' : 'secondary'} className="mt-1 h-5 px-1.5 text-[10px] pointer-events-none">
                                                {user.status}
                                            </Badge>
                                        </div>
                                    </div>
                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-foreground">
                                                <MoreVertical className="h-4 w-4" />
                                            </Button>
                                        </DropdownMenuTrigger>
                                        <DropdownMenuContent align="end">
                                            <DropdownMenuItem onClick={() => router.push(`/admin/users/${user.id}`)}>
                                                View Profile
                                            </DropdownMenuItem>
                                            <DropdownMenuItem className="text-destructive focus:text-destructive" onClick={() => setUserToDelete(user.id)}>
                                                <Trash2 className="mr-2 h-4 w-4" />
                                                Deactivate
                                            </DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                </div>

                                <div className="mt-6 space-y-2.5">
                                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                        <Mail className="h-3.5 w-3.5" />
                                        <span className="truncate">{user.email}</span>
                                    </div>
                                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                        <Phone className="h-3.5 w-3.5" />
                                        <span>{user.phone_number || 'N/A'}</span>
                                    </div>
                                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                        <Calendar className="h-3.5 w-3.5" />
                                        <span>Joined {user.created_at ? format(new Date(user.created_at), 'MMM yyyy') : 'Recently'}</span>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}
        </CardContent>
      </Card>

      <AlertDialog open={!!userToDelete} onOpenChange={() => setUserToDelete(null)}>
        <AlertDialogContent>
            <AlertDialogHeader>
                <AlertDialogTitle>Are you sure?</AlertDialogTitle>
                <AlertDialogDescription>
                    This will deactivate the user's account and prevent them from accessing the system.
                </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
                <AlertDialogCancel>Cancel</AlertDialogCancel>
                <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                    Deactivate
                </AlertDialogAction>
            </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import * as React from 'react';
import { Plus, Search, AlertTriangle } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { DamageReportList, useDamageReports, useCreateDamageReport, DamageReportForm } from '@/features/inventory';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';

export default function DamageReportsPage() {
  const { data: reports, isLoading, error } = useDamageReports();
  const createReport = useCreateDamageReport();
  const [searchQuery, setSearchQuery] = React.useState('');
  const [filter, setFilter] = React.useState('all');
  const [isDialogOpen, setIsDialogOpen] = React.useState(false);

  const filteredReports = React.useMemo(() => {
    if (!reports) return [];
    return reports.filter(report => {
      const matchesSearch = report.description?.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            report.items?.some(i => i.description?.toLowerCase().includes(searchQuery.toLowerCase()));
      const matchesFilter = filter === 'all' ? true : report.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [reports, searchQuery, filter]);

  const handleCreateReport = async (data: any) => {
    try {
      await createReport.mutateAsync(data);
      setIsDialogOpen(false);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-foreground">
            Damage Reports
          </h1>
          <p className="text-base text-muted-foreground mt-1">
            Track and manage reported damages to property and inventory.
          </p>
        </div>

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogTrigger asChild>
            <Button size="lg" className="bg-destructive hover:bg-destructive/90 text-destructive-foreground shadow-sm">
              <Plus className="h-5 w-5 mr-2" />
              Report Damage
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Report New Damage</DialogTitle>
              <DialogDescription>
                Create a new damage report for a unit or inventory item.
              </DialogDescription>
            </DialogHeader>
            <DamageReportForm 
              onSubmit={handleCreateReport} 
              isSubmitting={createReport.isPending}
            />
          </DialogContent>
        </Dialog>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <Tabs value={filter} onValueChange={setFilter} className="w-full md:w-auto">
          <TabsList>
            <TabsTrigger value="all">All Reports</TabsTrigger>
            <TabsTrigger value="pending">Pending</TabsTrigger>
            <TabsTrigger value="in_review">In Review</TabsTrigger>
            <TabsTrigger value="resolved">Resolved</TabsTrigger>
          </TabsList>
        </Tabs>

        <div className="relative w-full md:w-72">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input 
            placeholder="Search reports..." 
            className="pl-10"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Main Content Area */}
      {isLoading ? (
        <div className="space-y-4">
          {[1,2,3].map(i => (
            <Card key={i} className="h-32 animate-pulse bg-muted/50" />
          ))}
        </div>
      ) : error ? (
         <Card className="border-destructive/20 bg-destructive/5">
            <CardContent className="flex flex-col items-center justify-center p-12 text-center">
               <AlertTriangle className="h-10 w-10 text-destructive mb-4" />
               <h3 className="font-semibold text-lg text-destructive">Error loading reports</h3>
               <p className="text-muted-foreground">Please try refreshing the page or contact support.</p>
            </CardContent>
         </Card>
      ) : filteredReports.length === 0 ? (
         <Card className="border-dashed border-2">
            <CardContent className="flex flex-col items-center justify-center p-12 text-center min-h-[300px]">
               <div className="h-12 w-12 rounded-full bg-muted flex items-center justify-center mb-4">
                 <AlertTriangle className="h-6 w-6 text-muted-foreground" />
               </div>
               <h3 className="font-semibold text-lg">No Damage Reports</h3>
               <p className="text-muted-foreground max-w-sm mt-2">
                 There are currently no damage reports matching your criteria. Use the "Report Damage" button to create one.
               </p>
            </CardContent>
         </Card>
      ) : (
         <div className="min-h-[400px]">
            <DamageReportList reports={filteredReports} />
         </div>
      )}
    </div>
  );
}

"use client";

import * as React from 'react';
import Link from 'next/link';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";
import { 
  Users,
  Wrench,
  CheckCircle2,
  UserPlus,
  UserX,
  ClipboardList,
  ArrowRight,
} from 'lucide-react';

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils/cn";
import { useCaretakerDashboard } from "@/features/caretaker";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

export default function Page() {
  const { data: dashboardData, isLoading } = useCaretakerDashboard();

  // Real Data for Charts
  const weeklyStats = dashboardData?.maintenanceStats?.weeklyData || [];

  const barChartData = React.useMemo(
    () => ({
      labels: days,
      datasets: [
        {
          label: "New Issues",
          data: weeklyStats.map(d => d.new) || [],
          backgroundColor: "#0ea5e9", // Sky 500
          borderRadius: 4,
          barThickness: 24,
        },
        {
          label: "Resolved",
          data: weeklyStats.map(d => d.resolved) || [],
          backgroundColor: "#10b981", // Emerald 500
          borderRadius: 4,
          barThickness: 24,
        },
      ],
    }),
    [weeklyStats],
  );

  const barChartOptions = React.useMemo(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: "bottom" as const,
          labels: {
            usePointStyle: true,
            font: {
              family: 'inherit',
              size: 12
            }
          },
        },
        tooltip: {
          backgroundColor: '#1e293b',
          padding: 12,
          cornerRadius: 8,
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          grid: {
            color: 'rgba(0, 0, 0, 0.05)',
          },
          border: {
            display: false
          },
          ticks: {
            stepSize: 1,
            font: {
              family: 'inherit',
            }
          },
        },
        x: {
          grid: {
            display: false,
          },
          border: {
            display: false
          },
          ticks: {
            font: {
              family: 'inherit',
            }
          }
        }
      },
    }),
    [],
  );

  const kpiCards = [
    {
      label: "Pending Approvals",
      value: dashboardData?.todayOverview.pendingApprovals || 0,
      description: "Require attention",
      icon: ClipboardList,
      href: "/caretaker/approvals"
    },
    {
      label: "Check-Ins Today",
      value: dashboardData?.todayOverview.checkInsToday || 0,
      description: "Expected arrivals",
      icon: UserPlus,
      href: "/caretaker/check-in"
    },
    {
      label: "Check-Outs Today",
      value: dashboardData?.todayOverview.checkOutsToday || 0,
      description: "Departures scheduled",
      icon: UserX,
      href: "/caretaker/check-out"
    },
    {
      label: "Open Maintenance",
      value: dashboardData?.todayOverview.unresolvedIssues || 0,
      description: `${dashboardData?.maintenanceStats.highPriority || 0} high priority`,
      icon: Wrench,
      href: "/caretaker/maintenance"
    },
  ] as const;

  const quickActions = [
    {
      title: "Check In Student",
      href: "/caretaker/check-in",
      icon: UserPlus,
      variant: "default",
    },
    {
      title: "Check Out Student",
      href: "/caretaker/check-out",
      icon: UserX,
      variant: "outline",
    },
    {
      title: "Log Issue",
      href: "/caretaker/maintenance",
      icon: Wrench,
      variant: "outline",
    },
    {
      title: "View Tenants",
      href: "/caretaker/tenants",
      icon: Users,
      variant: "ghost",
    },
  ];

  if (isLoading) {
    return (
      <div className="space-y-8 p-1">
        <div className="space-y-2">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-4 w-96" />
        </div>
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          {[...Array(4)].map((_, i) => (
            <Skeleton key={i} className="h-32 rounded-xl" />
          ))}
        </div>
        <Skeleton className="h-96 w-full rounded-xl" />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header */}
      <div className="flex flex-col gap-1">
        <h1 className="text-3xl font-bold tracking-tight text-foreground">
          Dashboard
        </h1>
        <p className="text-base text-muted-foreground">
          Welcome back. Here's what's happening in your hostel today.
        </p>
      </div>

      {/* KPI Cards */}
      <section className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {kpiCards.map((card) => {
          const Icon = card.icon;
          return (
            <Link key={card.label} href={card.href}>
              <Card className="hover:shadow-md transition-all active:scale-95 duration-200 border shadow-sm">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-bold text-muted-foreground">
                    {card.label}
                  </CardTitle>
                  <Icon className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-3xl font-bold text-foreground">
                    {card.value.toLocaleString()}
                  </div>
                  <p className="text-xs font-medium text-muted-foreground mt-1">
                    {card.description}
                  </p>
                </CardContent>
              </Card>
            </Link>
          );
        })}
      </section>

      {/* Main Content Grid */}
      <div className="grid gap-6 lg:grid-cols-7">

        {/* Left Column: Charts & Quick Actions */}
        <div className="space-y-6 lg:col-span-5">
          {/* Quick Actions - Simplified & UX Focused */}
          <Card className="border-none shadow-none bg-transparent">
             <CardHeader className="px-0 pt-0">
              <CardTitle className="text-lg font-bold">Quick Actions</CardTitle>
            </CardHeader>
             <CardContent className="px-0 flex flex-wrap gap-3">
              {quickActions.map((action) => {
                const Icon = action.icon;
                return (
                  <Button
                    key={action.title}
                    variant={action.variant as any}
                    size="lg"
                    className="h-14 gap-2 text-base font-bold shadow-sm"
                    asChild
                  >
                    <Link href={action.href}>
                      <Icon className="h-5 w-5" />
                      {action.title}
                    </Link>
                  </Button>
                )
              })}
             </CardContent>
          </Card>

          {/* Maintenance Chart */}
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle className="text-lg font-bold">Weekly Maintenance</CardTitle>
              <CardDescription>Overview of reported and resolved issues</CardDescription>
            </CardHeader>
            <CardContent className="h-[350px] pl-0">
              <Bar data={barChartData} options={barChartOptions} />
            </CardContent>
          </Card>
        </div>

        {/* Right Column: Occupancy & Focus */}
        <div className="space-y-6 lg:col-span-2">
           {/* Today's Focus */}
           <Card className="bg-primary/5 border-primary/20 shadow-sm">
            <CardHeader className="pb-3">
              <CardTitle className="text-base font-bold flex items-center gap-2 text-primary">
                <CheckCircle2 className="h-5 w-5" />
                Today's Focus
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4 text-sm">
              <div className="p-3 bg-background rounded-lg border shadow-sm">
                <p className="font-medium text-foreground">Check-ins Pending</p>
                 <p className="text-muted-foreground mt-1">
                    You have <span className="font-bold text-foreground">{dashboardData?.todayOverview.checkInsToday}</span> students arriving today.
                 </p>
                 <Button variant="link" className="px-0 h-auto mt-2 text-primary" asChild>
                    <Link href="/caretaker/check-in">View Arrivals →</Link>
                 </Button>
              </div>

              <div className="p-3 bg-background rounded-lg border shadow-sm">
                <p className="font-medium text-foreground">Pending Approvals</p>
                 <p className="text-muted-foreground mt-1">
                    <span className="font-bold text-foreground">{dashboardData?.todayOverview.pendingApprovals}</span> requests need your review.
                 </p>
                 <Button variant="link" className="px-0 h-auto mt-2 text-primary" asChild>
                    <Link href="/caretaker/approvals">Process Requests →</Link>
                 </Button>
              </div>
            </CardContent>
          </Card>

          {/* Occupancy Donut/Stats simplified */}
          <Card className="shadow-sm">
             <CardHeader>
              <CardTitle className="text-lg font-bold">Occupancy</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
               <div className="flex items-end justify-between">
                  <span className="text-4xl font-bold">{dashboardData?.roomOccupancy.occupancyRate}%</span>
                  <span className="text-sm font-medium text-muted-foreground mb-1">Total Capacity</span>
               </div>
               <div className="w-full bg-secondary h-3 rounded-full overflow-hidden">
                  <div 
                    className="bg-primary h-full rounded-full transition-all duration-1000" 
                    style={{ width: `${dashboardData?.roomOccupancy.occupancyRate || 0}%` }}
                  />
               </div>
               <div className="grid grid-cols-2 gap-4 pt-2">
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Occupied</p>
                    <p className="text-xl font-bold">{dashboardData?.roomOccupancy.occupied}</p>
                  </div>
                   <div>
                    <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Available</p>
                    <p className="text-xl font-bold">{dashboardData?.roomOccupancy.available}</p>
                  </div>
               </div>
               <Button variant="outline" className="w-full" asChild>
                 <Link href="/caretaker/room-management">Manage Rooms</Link>
               </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import { useRouter } from 'next/navigation';
import { useInventoryStore } from '@/features/inventory';
import { 
  CheckCircle2, 
  Utensils, 
  Bed, 
  Bath, 
  Sofa, 
  Package, 
  Save, 
  Send,
  ArrowLeft,
  User,
  Calendar
} from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { InventoryCategorySection } from '@/features/inventory';
import { ComparisonView } from '@/features/inventory';
import type { InventoryCategory } from '@/features/inventory';
import { toast } from 'sonner';

import { use } from 'react';

interface PageProps {
  params: Promise<{
    reportId: string;
  }>;
}

export default function VerificationPage({ params }: PageProps) {
  const { reportId } = use(params);
  const router = useRouter();
  const { 
    activeReport, 
    isLoading, 
    error, 
    fetchReportById, 
    verifyItemLocal, 
    submitVerification 
  } = useInventoryStore();

  const [generalNote, setGeneralNote] = React.useState('');

  React.useEffect(() => {
    if (reportId) {
      fetchReportById(reportId);
    }
  }, [reportId, fetchReportById]);

  // Group items logic (reused from student view mostly)
  const groupedItems = React.useMemo(() => {
    if (!activeReport?.items) return {};

    const groups: Partial<Record<InventoryCategory, typeof activeReport.items>> = {};

    activeReport.items.forEach(item => {
      const cat = item.itemSnapshot.category || 'shared';
      if (!groups[cat]) groups[cat] = [];
      groups[cat]!.push(item);
    });

    return groups;
  }, [activeReport?.items]);

  const categories = Object.keys(groupedItems) as InventoryCategory[];

  const categoryIcons: Record<InventoryCategory, React.ElementType> = {
    kitchen: Utensils,
    bedroom: Bed,
    bathroom: Bath,
    living_area: Sofa,
    shared: Package,
  };

  const handleSubmit = async () => {
    await submitVerification(generalNote);
    router.push('/caretaker/inventory');
  };

  if (isLoading) {
    return (
       <div className="space-y-6 max-w-5xl mx-auto p-4 md:p-8">
        <Skeleton className="h-20 w-full" />
        <Skeleton className="h-[400px] w-full" />
      </div>
    );
  }

  if (!activeReport) {
    return (
      <div className="p-8 text-center text-muted-foreground">
        Report not found.
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto p-4 md:p-8 space-y-6 animate-in fade-in duration-500">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold tracking-tight">
            Verify {activeReport.type === 'check_in' ? 'Check-In' : 'Check-Out'}
          </h1>
          <div className="flex items-center gap-3 text-sm text-muted-foreground mt-1">
            <span className="flex items-center gap-1">
               <User className="h-4 w-4" /> Student ID: {activeReport.studentId}
            </span>
            <span>•</span>
            <span className="flex items-center gap-1">
               <Package className="h-4 w-4" /> Room {activeReport.roomNumber}
            </span>
            <span>•</span>
            <span className="flex items-center gap-1">
               <Calendar className="h-4 w-4" /> {new Date(activeReport.createdAt).toLocaleDateString()}
            </span>
          </div>
        </div>
        <div className="ml-auto">
             <Badge variant={
                 activeReport.status === 'submitted' ? 'secondary' : 
                 activeReport.status === 'verified' ? 'default' : 'outline'
             }>
                 {activeReport.status.toUpperCase()}
             </Badge>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Main Content (Items) */}
        <div className="lg:col-span-2 space-y-6">
          {categories.map((category) => {
            const catItems = groupedItems[category] || [];
            const Icon = categoryIcons[category] || Package;
            const completedCount = catItems.filter(i => i.caretakerCondition).length;

            return (
              <InventoryCategorySection
                key={category}
                title={category.charAt(0).toUpperCase() + category.slice(1).replace('_', ' ')}
                icon={Icon}
                count={catItems.length}
                completedCount={completedCount}
                defaultOpen={true}
              >
                <div className="space-y-4">
                  {catItems.map((item) => (
                    <ComparisonView
                      key={item.itemId}
                      item={item}
                      onVerify={(condition, isFlagged, comment, isChargeable, damageCost) => 
                        verifyItemLocal(item.itemId, condition, isFlagged, comment, isChargeable, damageCost)
                      }
                    />
                  ))}
                </div>
              </InventoryCategorySection>
            );
          })}
        </div>

        {/* Sidebar (Summary & Actions) */}
        <div className="space-y-6">
          <Card className="sticky top-6">
            <CardHeader>
              <CardTitle>Verification Summary</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2 text-sm">
                 <div className="flex justify-between">
                     <span className="text-muted-foreground">Total Items</span>
                     <span className="font-medium">{activeReport.items.length}</span>
                 </div>
                 <div className="flex justify-between">
                     <span className="text-muted-foreground">Flagged Issues</span>
                     <span className="font-bold text-amber-600">
                         {activeReport.items.filter(i => i.isFlagged).length}
                     </span>
                 </div>
                 {activeReport.type === 'check_out' && (
                     <div className="flex justify-between pt-2 border-t mt-2">
                         <span className="font-semibold">Total Damage Cost</span>
                         <span className="font-bold text-destructive">
                             KES {activeReport.items.reduce((acc, curr) => acc + (curr.damageCost || 0), 0).toLocaleString()}
                         </span>
                     </div>
                 )}
              </div>

              <div className="space-y-2">
                  <label className="text-sm font-medium">General Notes</label>
                  <Textarea 
                      placeholder="Any final remarks for the landlord..."
                      value={generalNote}
                      onChange={(e) => setGeneralNote(e.target.value)}
                      className="resize-none h-24"
                  />
              </div>

              <Button className="w-full gap-2" size="lg" onClick={handleSubmit}>
                 Complete Verification <CheckCircle2 className="h-4 w-4" />
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

