                              disabled={checkOutMutation.isPending}
                            >
                              Check Out
                            </Button>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>

          {/* Mobile Card View */}
          <div className="md:hidden space-y-4">
             {isLoading ? (
                <div className="text-center py-8 text-muted-foreground">Loading...</div>
