                    )}
                 </>
               ) : (
                  <div className="text-center py-4">
                     <p className="text-sm text-muted-foreground">Check-In Verification</p>
                     <p className="text-xl font-semibold mt-2 text-green-700">Ready for Move-In</p>
                  </div>
               )}
            </CardContent>
         </Card>
