// Custom tooltip for charts - theme adaptive
const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-card p-3 border border-border rounded-lg shadow-lg">
        <p className="text-sm font-bold text-foreground mb-2">{label}</p>
        {payload.map((entry: any, index: number) => (
          <p key={index} className="text-xs text-muted-foreground">
            <span className="font-semibold">{entry.name}:</span>{' '}
            {entry.name.includes('Revenue')
              ? `KES ${entry.value.toLocaleString()}`
              : `${entry.value}%`}
          </p>
        ))}
      </div>
    );
  }
  return null;
};

// Helper function to get activity icon
function getActivityIcon(type: string): React.ElementType {
  const iconMap: Record<string, React.ElementType> = {
    booking: CheckCircle2,
    payment: DollarSign,
    alert: Clock,
    maintenance: Clock,
    cancellation: Clock,
  };
  return iconMap[type] || Activity;
}

// Helper function to get activity color
function getActivityColor(type: string): string {
  const colorMap: Record<string, string> = {
    booking: 'text-green-600 dark:text-green-400',
    payment: 'text-blue-600 dark:text-blue-400',
    alert: 'text-orange-600 dark:text-orange-400',
    maintenance: 'text-orange-600 dark:text-orange-400',
    cancellation: 'text-red-600 dark:text-red-400',
  };
  return colorMap[type] || 'text-muted-foreground';
}

