// ============================================================================
// INVENTORY ITEM ROW COMPONENT
// ============================================================================

interface InventoryItemRowProps {
  item: InventoryItem;
  onToggle: () => void;
  onQuantityChange: (qty: number) => void;
  onPerBedToggle: () => void;
  onDelete?: () => void;
  showDelete?: boolean;
}

function InventoryItemRow({
  item,
  onToggle,
  onQuantityChange,
  onPerBedToggle,
  onDelete,
  showDelete,
}: InventoryItemRowProps) {
  const isActive = item.quantity > 0;

  return (
    <div
      className={cn(
        "flex items-center gap-3 p-3 rounded-lg border transition-all",
        isActive ? "border-primary/30 bg-primary/5" : "border-muted bg-muted/30 opacity-60"
      )}
    >
      <Checkbox
        checked={isActive}
        onCheckedChange={onToggle}
        className="h-5 w-5"
      />
      <div className="flex-1 min-w-0">
        <p className={cn(
          "text-base font-semibold truncate",
          isActive ? "text-foreground" : "text-muted-foreground"
        )}>
          {item.name}
        </p>
        <div className="flex items-center gap-2 mt-1">
          <Badge
            variant="outline"
            className={cn(
              "text-xs cursor-pointer transition-colors",
              item.perBed && "bg-blue-50 border-blue-200 text-blue-700 dark:bg-blue-950 dark:border-blue-800 dark:text-blue-300"
            )}
            onClick={onPerBedToggle}
          >
            {item.perBed ? 'Per Bed' : 'Per Room'}
          </Badge>
          {item.price && (
            <span className="text-xs text-muted-foreground">
              KES {item.price.toLocaleString()}
            </span>
          )}
        </div>
      </div>
      <div className="flex items-center gap-2">
        <div className="flex items-center gap-1">
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8"
            onClick={() => onQuantityChange(item.quantity - 1)}
            disabled={item.quantity <= 0}
          >
            -
          </Button>
          <span className="w-8 text-center font-bold text-foreground">
            {item.quantity}
          </span>
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8"
            onClick={() => onQuantityChange(item.quantity + 1)}
          >
            +
          </Button>
        </div>
        {showDelete && onDelete && (
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-red-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-950"
            onClick={onDelete}
          >
            <Trash2 className="h-4 w-4" />
          </Button>
        )}
      </div>
    </div>
  );
}

