      if (!booking) return;

      processCheckIn.mutate({
          tenantId: typeof booking.student === 'object' ? booking.student?.id || '' : booking.student || '',
          bookingCode: booking.booking_reference || 'MANUAL',
          roomId: typeof booking.room === 'object' ? booking.room?.id || '' : '',
