                      {item.title}
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              );
            }

            return isExpanded ? (
              <Button
                key={index}
                asChild
                variant="ghost"
                className={cn(
                  'w-full justify-start font-bold text-base text-foreground hover:bg-accent hover:text-accent-foreground transition-all duration-200',
                  is_active &&
                    'bg-primary/10 text-primary hover:bg-primary/20 hover:text-primary',
                )}
