        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <label className="text-sm font-medium text-foreground flex items-center gap-1">
              Gender <span className="text-destructive">*</span>
            </label>
            <select
              {...register('gender')}
              className="flex h-11 w-full rounded-none border border-gray-300 bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary disabled:cursor-not-allowed disabled:opacity-50 transition-colors"
            >
              <option value="male">Male</option>
              <option value="female">Female</option>
              <option value="other">Other</option>
            </select>
            {errors.gender && (
              <p className="text-sm text-destructive">{errors.gender.message}</p>
            )}
          </div>

          <FormField
            label="Date of Birth"
            type="date"
            error={errors.date_of_birth?.message}
            required
            {...register('date_of_birth')}
          />
        </div>

        <FormField
          label="School (University)"
          placeholder="University of Nairobi"
          error={errors.university?.message}
          required
          {...register('university')}
        />

        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <label className="text-sm font-medium text-foreground">
              Hostel (Optional)
            </label>
            <select
              {...register('preferred_hostel_id')}
              className="flex h-11 w-full rounded-none border border-gray-300 bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary transition-colors"
            >
              <option value="">I haven't picked one yet</option>
              {hostels.map((h) => (
                <option key={h.id} value={h.id}>{h.name}</option>
              ))}
            </select>
          </div>

          <FormField
            label="Room Number (Optional)"
            placeholder="A12"
            error={errors.room_number?.message}
            {...register('room_number')}
          />
        </div>

        <PasswordField
          label="Password"
          placeholder="Create a strong password"
          autoComplete="new-password"
          error={errors.password?.message}
          required
          showStrength
          {...register('password')}
        />

        <PasswordField
          label="Confirm password"
          placeholder="Re-enter your password"
          autoComplete="new-password"
          error={errors.confirm_password?.message}
          required
          {...register('confirm_password')}
        />

        <div className="text-xs text-center text-gray-500 font-bold uppercase tracking-wider">
          By selecting <strong>Create student account</strong>, I agree to the{' '}
          <Link
            href="/terms"
            className="text-primary hover:underline underline-offset-4"
          >
            Terms of Service
          </Link>{' '}
          and{' '}
          <Link
            href="/privacy"
            className="text-primary hover:underline underline-offset-4"
          >
            Privacy Policy
          </Link>
          .
        </div>

        <Button
          type="submit"
          className="w-full h-12 text-base font-black bg-primary hover:bg-primary/90 text-white rounded-none uppercase tracking-widest shadow-md active:translate-y-0.5 transition-all"
          disabled={isSubmitting}
        >
          {isSubmitting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden />
              Creating account...
            </>
          ) : (
            'Create student account'
          )}
        </Button>
      </form>
    </section>
  );
}

'use client';

import { formatDistanceToNow } from 'date-fns';
import { ActivityEvent } from '@/features/student';
import { cn } from '@/lib/utils';
import { Bell, CreditCard, FileText, Home, Info, MessageSquare, Settings, User, CheckCircle2 } from 'lucide-react';

interface RecentActivityProps {
  activities: ActivityEvent[];
  className?: string;
}

const getActivityIcon = (type: string) => {
  switch (type) {
    case 'payment':
      return <CreditCard className="h-4 w-4" />;
    case 'booking':
      return <Home className="h-4 w-4" />;
    case 'ticket':
      return <FileText className="h-4 w-4" />;
    case 'message':
      return <MessageSquare className="h-4 w-4" />;
    case 'profile':
      return <User className="h-4 w-4" />;
    case 'system':
      return <Settings className="h-4 w-4" />;
    default:
      return <Info className="h-4 w-4" />;
  }
};

// Premium color palette for activity types
const getActivityStyles = (type: string) => {
  switch (type) {
    case 'payment':
      return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
    case 'booking':
      return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
    case 'ticket':
      return 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400';
    case 'message':
      return 'bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-400';
    case 'profile':
      return 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400';
    default:
      return 'bg-gray-100 text-gray-600 dark:bg-muted dark:text-muted-foreground';
  }
};

export function RecentActivity({ activities, className }: RecentActivityProps) {
  if (!activities?.length) {
    return (
      <div className={cn("rounded-3xl border border-dashed p-8 text-center", className)}>
        <div className="mx-auto h-12 w-12 rounded-full bg-muted flex items-center justify-center mb-4">
            <Bell className="h-6 w-6 text-muted-foreground/50" />
        </div>
        <h3 className="font-semibold text-foreground">No recent updates</h3>
        <p className="text-sm text-muted-foreground mt-1">When something happens, you'll see it here.</p>
      </div>
    );
  }

  return (
    <div className={cn("space-y-6", className)}>
      <div className="flex items-center justify-between">
         <h3 className="text-lg font-bold tracking-tight">Timeline</h3>
         {/* Optional filter or view all button could go here */}
      </div>

      <div className="relative space-y-8 pl-2">
        {/* Continuous Line */}
        <div className="absolute left-[19px] top-6 bottom-6 w-[2px] bg-gradient-to-b from-border via-border/50 to-transparent" />

        {activities.map((activity, index) => (
          <div key={activity.id || index} className="relative flex gap-6 group">
            {/* Timeline Node */}
            <div
              className={cn(
                "relative z-10 flex h-10 w-10 shrink-0 items-center justify-center rounded-full shadow-sm ring-4 ring-background transition-transform group-hover:scale-110 duration-300",
                getActivityStyles(activity.type)
              )}
            >
              {getActivityIcon(activity.type)}
            </div>

            {/* Content */}
            <div className="flex flex-col gap-1.5 pt-1.5 min-w-0 flex-1">
              <div className="flex items-center justify-between">
                 <p className="text-sm font-bold text-foreground leading-none group-hover:text-primary transition-colors">
                    {activity.title}
                 </p>
                 <span className="text-[10px] font-medium text-muted-foreground/80 bg-muted/50 px-2 py-0.5 rounded-full whitespace-nowrap">
                    {formatDistanceToNow(new Date(activity.timestamp), { addSuffix: true })}
                 </span>
              </div>
              <p className="text-xs md:text-sm font-medium text-muted-foreground leading-relaxed">
                {activity.description}
              </p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

