'use client';

import { Suspense, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Skeleton } from '@/components/ui/skeleton';
import { getHostelBySlug, hostelsApi } from '@/features/hostels';
import { useAuth } from '@/features/auth/hooks/use-auth';
import type { Hostel, Room } from '@/types/entities.types';

// New specialized variants
import PublicHostelDetail from './public-hostel-detail';
import DashboardHostelDetail from './dashboard-hostel-detail';

interface HostelDetailClientProps {
  slug: string;
}

export function HostelDetailClient({ slug }: HostelDetailClientProps) {
  const { user, isAuthenticated } = useAuth();

  // Fetch the hostel
  const {
    data: rawHostel,
    isLoading: isLoadingHostel,
    error: hostelError,
  } = useQuery<Hostel>({
    queryKey: ['hostel', slug],
    queryFn: () => getHostelBySlug(slug),
    retry: 1,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  // Fetch rooms for this hostel if not included in hostel response
  const {
    data: roomsResponse,
    isLoading: isLoadingRooms,
  } = useQuery({
    queryKey: ['hostel-rooms', rawHostel?.id],
    queryFn: () => hostelsApi.getRooms({ hostel: rawHostel?.id }),
    enabled: Boolean(rawHostel?.id) && (!rawHostel?.rooms || rawHostel.rooms.length === 0),
    staleTime: 5 * 60 * 1000,
  });

  const isLoading = isLoadingHostel || isLoadingRooms;

  // Combine hostel with rooms data
  const hostel = useMemo(() => {
    if (!rawHostel) return null;

    // Use rooms from hostel response if available, otherwise use separately fetched rooms
    const rooms: Room[] = (rawHostel?.rooms && rawHostel.rooms.length > 0)
      ? rawHostel.rooms
      : (roomsResponse?.data || []);

    return {
      ...rawHostel,
      rooms,
      reviews: rawHostel?.reviews || [],
    } as Hostel;
  }, [rawHostel, roomsResponse]);

  if (isLoading) {
    return (
      <div className="container mx-auto py-8 md:py-12 px-4 sm:px-6 lg:px-8 max-w-7xl">
        <div className="space-y-8">
          <Skeleton className="h-12 w-2/3" />
          <Skeleton className="h-[500px] w-full rounded-xl" />
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:col-span-2 space-y-12">
              <Skeleton className="h-64 w-full" />
              <Skeleton className="h-64 w-full" />
            </div>
            <Skeleton className="h-96 w-full" />
          </div>
        </div>
      </div>
    );
  }

  if (hostelError || !hostel) {
    return (
      <div className="container mx-auto py-16 px-4 text-center">
        <div className="max-w-md mx-auto">
          <div className="mb-4 text-6xl">🏠</div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Hostel Not Found</h1>
          <p className="text-gray-600 mb-6">
            The hostel you're looking for could not be found or has been removed.
          </p>
          <button
            onClick={() => window.history.back()}
            className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-medium transition-colors"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  // Determine which variant to show
  // If authenticated as a student, show the personalized dashboard view
  if (isAuthenticated && user?.role === 'student') {
    return (
      <DashboardHostelDetail 
        hostel={hostel} 
        studentContext={{
          roommateMatchScore: 85, // Mock score - should come from backend
          isSaved: hostel.is_favorited || false,
          applicationStatus: 'none'
        }}
      />
    );
  }

  // Default to Public View (SEO & Marketing focused)
  return <PublicHostelDetail hostel={hostel} />;
}

'use client';

import * as React from 'react';
import Image from 'next/image';
import { motion, AnimatePresence, PanInfo } from 'framer-motion';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { 
  X,
  ChevronLeft, 
  ChevronRight,
  Maximize2,
  Grid3x3
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface HostelGalleryProps {
  images: string[];
  hostelName?: string;
}

/**
 * HostelGallery - Airbnb-inspired photo gallery
 * Large primary image with grid of thumbnails
 * Full-screen lightbox with keyboard navigation and mobile swipe support
 */
export default function HostelGallery({ images, hostelName }: HostelGalleryProps) {
  const [lightboxOpen, setLightboxOpen] = React.useState(false);
  const [currentIndex, setCurrentIndex] = React.useState(0);
  const [direction, setDirection] = React.useState(0);

  if (!images.length) return null;

  const visibleImages = images.slice(0, 5);
  const remainingCount = images.length - 5;

  const openLightbox = (index: number) => {
    setCurrentIndex(index);
    setLightboxOpen(true);
  };

  const navigate = (newDirection: number) => {
    setDirection(newDirection);
    setCurrentIndex((prevIndex) => {
      let nextIndex = prevIndex + newDirection;
      if (nextIndex < 0) nextIndex = images.length - 1;
      if (nextIndex >= images.length) nextIndex = 0;
      return nextIndex;
    });
  };

  const handleDragEnd = (e: any, { offset, velocity }: PanInfo) => {
    const swipe = Math.abs(offset.x) * velocity.x;

    if (swipe < -10000) {
      navigate(1);
    } else if (swipe > 10000) {
      navigate(-1);
    }
  };

  // Keyboard navigation
  React.useEffect(() => {
    if (!lightboxOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowLeft') navigate(-1);
      if (e.key === 'ArrowRight') navigate(1);
      if (e.key === 'Escape') setLightboxOpen(false);
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [lightboxOpen]);

  const variants = {
    enter: (direction: number) => ({
      x: direction > 0 ? 1000 : -1000,
      opacity: 0,
      scale: 0.95,
    }),
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1,
      scale: 1,
    },
    exit: (direction: number) => ({
      zIndex: 0,
      x: direction < 0 ? 1000 : -1000,
      opacity: 0,
      scale: 0.95,
    }),
  };

  return (
    <>
      {/* Gallery Grid - Airbnb Style */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.1 }}
        className="relative"
      >
        {/* Desktop Grid */}
        <div className="hidden md:grid md:grid-cols-4 md:grid-rows-2 gap-2 h-[400px] lg:h-[500px] rounded-xl overflow-hidden">
          {/* Large primary image - left side */}
          <button
            onClick={() => openLightbox(0)}
            className="col-span-2 row-span-2 relative group overflow-hidden"
          >
            <Image
              src={images[0]}
              alt={hostelName ? `${hostelName} - Main photo` : 'Main photo'}
              fill
              className="object-cover transition-transform duration-500 group-hover:scale-105"
              priority
              sizes="(max-width: 768px) 100vw, 50vw"
            />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors duration-300" />
          </button>

          {/* Grid of 4 smaller images - right side */}
          {visibleImages.slice(1).map((img, i) => (
            <button
              key={i}
              onClick={() => openLightbox(i + 1)}
              className="relative group overflow-hidden"
            >
              <Image
                src={img}
                alt={`Photo ${i + 2}`}
                fill
                className="object-cover transition-transform duration-500 group-hover:scale-105"
                sizes="(max-width: 768px) 50vw, 25vw"
              />
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors duration-300" />

              {/* Show more overlay on last image */}
              {i === 3 && remainingCount > 0 && (
                <div className="absolute inset-0 bg-black/60 flex items-center justify-center text-white font-semibold">
                  <div className="flex items-center gap-2">
                    <Grid3x3 className="h-5 w-5" />
                    <span>+{remainingCount} photos</span>
                  </div>
                </div>
              )}
            </button>
          ))}
        </div>

        {/* Mobile: Single large image */}
        <div className="md:hidden relative aspect-[4/3] rounded-xl overflow-hidden">
          <button
            onClick={() => openLightbox(0)}
            className="w-full h-full relative"
          >
            <Image
              src={images[0]}
              alt={hostelName ? `${hostelName} - Main photo` : 'Main photo'}
              fill
              className="object-cover"
              priority
              sizes="100vw"
            />
          </button>
        </div>

        {/* View all photos button */}
        <Button
          variant="secondary"
          size="sm"
          onClick={() => openLightbox(0)}
          className="absolute bottom-4 right-4 gap-2 bg-white hover:bg-gray-100 shadow-lg border border-gray-200 font-semibold"
        >
          <Grid3x3 className="h-4 w-4" />
          <span className="hidden sm:inline">Show all photos</span>
          <span className="sm:hidden">Photos</span>
        </Button>
      </motion.div>

      {/* Lightbox Modal */}
      <Dialog open={lightboxOpen} onOpenChange={setLightboxOpen}>
        <DialogContent className="max-w-[100vw] max-h-[100vh] w-full h-full p-0 bg-black/95 border-0">
          <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
            {/* Close button */}
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setLightboxOpen(false)}
              className="absolute top-4 right-4 z-50 text-white hover:bg-white/20 rounded-full"
            >
              <X className="h-6 w-6" />
            </Button>

            {/* Image counter */}
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 bg-black/60 backdrop-blur-sm px-4 py-2 rounded-full">
              <p className="text-white text-sm font-medium">
                {currentIndex + 1} / {images.length}
              </p>
            </div>

            {/* Main image with swipe */}
            <AnimatePresence initial={false} custom={direction}>
              <motion.div
                key={currentIndex}
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{
                  x: { type: "spring", stiffness: 300, damping: 30 },
                  opacity: { duration: 0.2 }
                }}
                drag="x"
                dragConstraints={{ left: 0, right: 0 }}
                dragElastic={1}
                onDragEnd={handleDragEnd}
                className="absolute w-full h-full flex items-center justify-center"
              >
                <div className="relative w-full h-full max-w-7xl max-h-[90vh] mx-auto">
                  <Image
                    src={images[currentIndex]}
                    alt={`Photo ${currentIndex + 1}`}
                    fill
                    className="object-contain"
                    sizes="100vw"
                    draggable={false}
                  />
                </div>
              </motion.div>
            </AnimatePresence>

            {/* Navigation buttons (Desktop) */}
            {images.length > 1 && (
              <>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => navigate(-1)}
                  className="hidden md:flex absolute left-4 top-1/2 -translate-y-1/2 text-white hover:bg-white/20 rounded-full h-12 w-12 z-50"
                >
                  <ChevronLeft className="h-8 w-8" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => navigate(1)}
                  className="hidden md:flex absolute right-4 top-1/2 -translate-y-1/2 text-white hover:bg-white/20 rounded-full h-12 w-12 z-50"
                >
                  <ChevronRight className="h-8 w-8" />
                </Button>
              </>
            )}

            {/* Thumbnail strip (desktop only) */}
            <div className="hidden lg:block absolute bottom-4 left-0 right-0 px-4 z-50">
              <div className="max-w-4xl mx-auto">
                <div className="flex gap-2 overflow-x-auto scrollbar-hide justify-center">
                  {images.map((img, i) => (
                    <button
                      key={i}
                      onClick={() => {
                        setDirection(i > currentIndex ? 1 : -1);
                        setCurrentIndex(i);
                      }}
                      className={cn(
                        'relative w-20 h-20 rounded-lg overflow-hidden flex-shrink-0 transition-all',
                        i === currentIndex
                          ? 'ring-2 ring-white opacity-100'
                          : 'opacity-60 hover:opacity-80'
                      )}
                    >
                      <Image
                        src={img}
                        alt={`Thumbnail ${i + 1}`}
                        fill
                        className="object-cover"
                        sizes="80px"
                      />
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import * as React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  SlidersHorizontal, 
  X,
  Sparkles,
  Home
} from 'lucide-react';

import HostelSort from './hostel-sort';
import HostelGrid from './hostel-grid';
import { HostelFiltersPanel, type FiltersState } from './hostel-filters-panel';
import { useFiltersStore } from '@/features/hostels';
import { searchHostels, getHostels, type HostelsResponse } from '@/features/hostels';
import type { Hostel } from '@/types/entities.types';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

/**
 * HostelsView - Main discovery page for browsing hostels
 * Airbnb-inspired design with filters, sorting, and grid layout
 */
export function HostelsView() {
  const { 
    priceRange,
    amenities,
    searchQuery,
    sort,
    setPriceRange,
    toggleAmenity,
    setSearchQuery,
    resetFilters,
    university,
    city,
    hostel_type,
    gender_policy,
    setFilter
  } = useFiltersStore();

  const [isFiltersOpen, setIsFiltersOpen] = React.useState(false);

  // Combine store and local filters for API
  const apiFilters = React.useMemo(() => {
    // Map frontend sort keys to backend 'sort_by' parameter
    let sort_by = undefined;
    if (sort === 'price_asc') sort_by = 'price_low';
    else if (sort === 'price_desc') sort_by = 'price_high';
    else if (sort === 'rating') sort_by = 'rating';
    else if (sort === 'popularity') sort_by = 'popularity';

    return {
      university,
      city,
      hostel_type,
      gender_policy,
      min_price: priceRange[0],
      max_price: priceRange[1],
      amenities: amenities.length > 0 ? amenities.join(',') : undefined,
      search: searchQuery || undefined,
      sort_by,
    };
  }, [university, city, hostel_type, gender_policy, priceRange, amenities, searchQuery, sort]);

  const {
    data,
    isLoading,
    error,
  } = useQuery<HostelsResponse, Error>({
    queryKey: ['hostels', apiFilters, sort],
    queryFn: () => {
      // Use searchHostels only when there are meaningful filters that require authentication
      // Otherwise use getHostels which is publicly accessible
      const hasFilters = Object.keys(apiFilters).some(key => {
        const value = apiFilters[key as keyof typeof apiFilters];
        // Check for meaningful filter values, not just defaults or empty states
        if (value === undefined || value === '') return false;
        if (Array.isArray(value)) return value.length > 0;
        // Exclude default price range values
        if (key === 'min_price' && value === 0) return false;
        if (key === 'max_price' && value === 50000) return false;
        // Exclude default sort
        if (key === 'sort_by' && value === undefined) return false;
        return true;
      });

      console.log('🔍 Filter Logic:', { hasFilters, apiFilters });

      return hasFilters ? searchHostels(apiFilters) : getHostels({});
    },
    staleTime: 5 * 60 * 1000,
    retry: 1,
  });

  const hostels = data?.results || [];

  // Debug: Log data state
  console.log('🏠 Hostels Debug:', {
    data: data,
    hostelsLength: hostels.length,
    isLoading,
    error: error?.message,
    apiFilters
  });

  const handleFiltersChange = (newFilters: FiltersState) => {
    // Sync everything to store
    if (newFilters.university !== undefined) setFilter('university', newFilters.university);
    if (newFilters.city !== undefined) setFilter('city', newFilters.city);
    if (newFilters.hostel_type !== undefined) setFilter('hostel_type', newFilters.hostel_type);
    if (newFilters.gender_policy !== undefined) setFilter('gender_policy', newFilters.gender_policy);

    if (newFilters.min_price !== undefined && newFilters.max_price !== undefined) {
      setPriceRange([newFilters.min_price, newFilters.max_price]);
    }

    // For amenities, since store has toggle but panel passes full list:
    if (newFilters.amenities !== undefined) {
      setFilter('amenities', newFilters.amenities);
    }
  };

  const handleClearFilters = () => {
    resetFilters();
  };

  const activeFiltersCount = React.useMemo(() => {
    let count = 0;
    if (university) count++;
    if (city) count++;
    if (hostel_type) count++;
    if (gender_policy) count++;
    if (priceRange[0] !== 0 || priceRange[1] !== 50000) count++;
    if (amenities.length > 0) count += amenities.length;
    if (searchQuery) count++;
    return count;
  }, [university, city, hostel_type, gender_policy, priceRange, amenities, searchQuery]);

  // Error state
  if (error) {
    return (
      <div className="container mx-auto py-24 px-4 sm:px-6 lg:px-8 text-center">
        <div className="max-w-md mx-auto">
          <div className="mb-4 text-6xl">😕</div>
          <h2 className="text-2xl font-bold text-gray-900 mb-2">
            Something went wrong
          </h2>
          <p className="text-gray-600 mb-6">
            We couldn't load the hostels. Please try again later.
          </p>
          <Button 
            onClick={() => window.location.reload()}
            className="bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700"
          >
            Reload page
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Toolbar - Sticky below header */}
      <div className="sticky top-[72px] md:top-[68px] z-30 bg-white border-b shadow-sm transition-all">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between py-3 gap-4">
            {/* Results Count */}
            <div className="flex items-center gap-3">
              <Sheet open={isFiltersOpen} onOpenChange={setIsFiltersOpen}>
                <SheetTrigger asChild>
                  <Button 
                    variant="outline" 
                    className="relative h-10 gap-2 border border-gray-200 bg-white hover:bg-gray-50 hover:border-gray-300 text-gray-900 transition-all font-medium rounded-md shadow-sm"
                  >
                    <SlidersHorizontal className="h-4 w-4" />
                    <span className="hidden sm:inline">Filters</span>
                    {activeFiltersCount > 0 && (
                      <Badge className="ml-1 h-5 w-5 rounded-full p-0 flex items-center justify-center bg-gray-900 text-white text-xs">
                        {activeFiltersCount}
                      </Badge>
                    )}
                  </Button>
                </SheetTrigger>
                <SheetContent side="left" className="w-full sm:max-w-md p-0">
                  <HostelFiltersPanel
                    filters={{
                      university,
                      city,
                      hostel_type,
                      gender_policy,
                      min_price: priceRange[0],
                      max_price: priceRange[1],
                      amenities: amenities
                    }}
                    onFiltersChange={handleFiltersChange}
                    onClearFilters={handleClearFilters}
                    onClose={() => setIsFiltersOpen(false)}
                  />
                </SheetContent>
              </Sheet>

              {!isLoading && (
                <div className="hidden sm:block">
                  <p className="text-sm text-gray-600">
                    <span className="font-semibold text-gray-900">{hostels.length}</span>
                    {' '}hostels found
                  </p>
                </div>
              )}
            </div>

            {/* Right Actions */}
            <div className="flex items-center gap-2">
              <HostelSort />
            </div>
          </div>

          {/* Active Filters Pills */}
          <AnimatePresence>
            {activeFiltersCount > 0 && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden"
              >
                <div className="flex items-center gap-2 pb-3 overflow-x-auto scrollbar-hide">
                  <span className="text-xs text-gray-500 font-medium whitespace-nowrap">
                    Active filters:
                  </span>
                  {university && (
                    <Badge 
                      variant="secondary" 
                      className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 whitespace-nowrap"
                    >
                      🎓 {university}
                      <button
                        onClick={() => setFilter('university', undefined)}
                        className="ml-1 hover:text-emerald-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  )}
                  {city && (
                    <Badge 
                      variant="secondary" 
                      className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 whitespace-nowrap"
                    >
                      📍 {city}
                      <button
                        onClick={() => setFilter('city', undefined)}
                        className="ml-1 hover:text-emerald-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  )}
                  {hostel_type && (
                    <Badge 
                      variant="secondary" 
                      className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 whitespace-nowrap"
                    >
                      🏠 {hostel_type.replace('_', ' ')}
                      <button
                        onClick={() => setFilter('hostel_type', undefined)}
                        className="ml-1 hover:text-emerald-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  )}
                  {gender_policy && (
                    <Badge 
                      variant="secondary" 
                      className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 whitespace-nowrap"
                    >
                      👥 {gender_policy.replace('_', ' ')}
                      <button
                        onClick={() => setFilter('gender_policy', undefined)}
                        className="ml-1 hover:text-emerald-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  )}
                  {amenities?.map((amenity) => (
                    <Badge 
                      key={amenity}
                      variant="secondary" 
                      className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1 whitespace-nowrap"
                    >
                      ✨ {amenity}
                      <button
                        onClick={() => toggleAmenity(amenity)}
                        className="ml-1 hover:text-emerald-900"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleClearFilters}
                    className="text-xs text-gray-400 hover:text-gray-900 h-auto py-1 whitespace-nowrap"
                  >
                    Clear all
                  </Button>
                </div>
              </motion.div>
