describe('PaymentStatusTracker', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('should poll payment status every 5 seconds', async () => {
    const apiClient = require('@/lib/api/client').default;
    apiClient.axios.get.mockResolvedValue({
      data: {
        data: {
          status: 'pending',
        },
      },
    });

    const { PaymentStatusTracker } = require('@/features/payments/components/payment-status-tracker');

    render(
      <PaymentStatusTracker transactionRef="TXN-123" />,
      { wrapper: createWrapper() }
    );

    // Should call immediately
    await waitFor(() => {
      expect(apiClient.axios.get).toHaveBeenCalledTimes(1);
    });

    // Advance by 5 seconds
    await React.act(async () => {
      jest.advanceTimersByTime(5000);
    });

    await waitFor(() => {
      expect(apiClient.axios.get).toHaveBeenCalledTimes(2);
    });
  });

  it('should stop polling when status is success', async () => {
    const apiClient = require('@/lib/api/client').default;
    apiClient.axios.get
      .mockResolvedValueOnce({
        data: { data: { status: 'pending' } },
      })
      .mockResolvedValueOnce({
        data: { data: { status: 'success', mpesa_receipt: 'RCPT123' } },
      });

    const { PaymentStatusTracker } = require('@/features/payments/components/payment-status-tracker');

    render(
      <PaymentStatusTracker transactionRef="TXN-123" />,
      { wrapper: createWrapper() }
    );

    await React.act(async () => {
      jest.advanceTimersByTime(5000);
    });

    await React.act(async () => {
      jest.advanceTimersByTime(5000); // Second advance just in case
    });

    // Wait for the mock to be called and UI to update
    await waitFor(() => {
      expect(screen.getByText(/Payment confirmed/i)).toBeInTheDocument();
    }, { timeout: 5000 });

    // Should stop polling
    const initialCallCount = apiClient.axios.get.mock.calls.length;

    await React.act(async () => {
      jest.advanceTimersByTime(20000); 
    });

    expect(apiClient.axios.get.mock.calls.length).toBe(initialCallCount);
  });
});

